def get_subtitle_code(key: str) -> tuple[str, str]:
    """语言 key -> (ISO 639-2 代码, 显示名称)。

    与 C# 一致：先把 ``zh-hans`` 这种小写地区码规范为 ``zh-Hans``。
    """
    match = _NON_CAPS_RE.search(key)
    if match:
        key = key.replace(match.group(), match.group().upper())
    return _SUBTITLE_CODES.get(key, ("und", "Undetermined"))


# ---------------------------------------------------------------------------
# 各个字幕接口
# ---------------------------------------------------------------------------


def _get_intl_subtitles_api1(aid: str, cid: str, ep_id: str, index: int) -> list[Subtitle] | None:
    try:
        subtitles: list[Subtitle] = []
        host = "api.biliintl.com" if Config.EPHOST == "api.bilibili.com" else Config.EPHOST
        payload = json.loads(
            HTTPUtil.get_web_source(
                f"https://{host}/intl/gateway/web/v2/subtitle?episode_id={ep_id}"
            )
        )
        for sub in (payload.get("data") or {}).get("subtitles") or []:
            lan = str(sub.get("lang_key", ""))
            url = str(sub.get("url", ""))
            suffix = ".srt" if ".json" in url else ".ass"
            if any(not item.url for item in subtitles):
                raise RuntimeError("Bad url")
            subtitles.append(Subtitle(lan=lan, url=url, path=f"{aid}/{aid}.{cid}.{lan}{suffix}"))
        return subtitles
    except Exception:
        return None


def _get_intl_subtitles_api2(aid: str, cid: str, ep_id: str, index: int) -> list[Subtitle] | None:
    try:
        subtitles: list[Subtitle] = []
        host = "api.bilibili.tv" if Config.HOST == "api.bilibili.com" else Config.HOST
        url = f"https://{host}/intl/gateway/v2/ogv/view/app/season?ep_id={ep_id}"
        url += "&platform=android&s_locale=zh_SG"
        if Config.TOKEN != "":
            url += f"&access_key={Config.TOKEN}"
        payload = json.loads(HTTPUtil.get_web_source(url))
        episodes = ((payload.get("result") or {}).get("modules") or [{}])[0].get("data", {}).get(
            "episodes", []
        )
        node = episodes[index - 1] if 0 < index <= len(episodes) else {}
        for sub in node.get("subtitles") or []:
            lan = str(sub.get("key", ""))
            item_url = str(sub.get("url", "")).replace("\\\\/", "/")
            suffix = ".srt" if ".json" in item_url else ".ass"
            if any(not item.url for item in subtitles):
                raise RuntimeError("Bad url")
            subtitles.append(
                Subtitle(lan=lan, url=item_url, path=f"{aid}/{aid}.{cid}.{lan}{suffix}")
            )
        return subtitles
    except Exception:
        return None


def _get_subtitles_api1(aid: str, cid: str, ep_id: str, index: int) -> list[Subtitle] | None:
    try:
        subtitles: list[Subtitle] = []
        payload = json.loads(
            HTTPUtil.get_web_source(
                f"https://api.bilibili.com/x/web-interface/view?aid={aid}&cid={cid}"
            )
        )
        for sub in ((payload.get("data") or {}).get("subtitle") or {}).get("list") or []:
            lan = str(sub.get("lan", ""))
            subtitles.append(
                Subtitle(
                    lan=lan,
                    url=str(sub.get("subtitle_url", "")),
                    path=f"{aid}/{aid}.{cid}.{lan}.srt",
                )
            )
        if any(not item.url for item in subtitles):
            raise RuntimeError("Bad url")
        return subtitles
    except Exception:
        return None


def _get_subtitles_api2(aid: str, cid: str, ep_id: str, index: int) -> list[Subtitle] | None:
    try:
        subtitles: list[Subtitle] = []
        payload = json.loads(
            HTTPUtil.get_web_source(
                f"https://api.bilibili.com/x/player/wbi/v2?cid={cid}&aid={aid}"
            )
        )
        node = ((payload.get("data") or {}).get("subtitle") or {})
        for sub in node.get("subtitles") or []:
            lan = str(sub.get("lan", ""))
            subtitles.append(
                Subtitle(
                    lan=lan,
                    url=str(sub.get("subtitle_url", "")),
                    path=f"{aid}/{aid}.{cid}.{lan}.srt",
                )
            )
        if any(not item.url for item in subtitles):
            raise RuntimeError("Bad url")
        return subtitles
    except Exception:
        return None


def _get_subtitles_api3(aid: str, cid: str, ep_id: str, index: int) -> list[Subtitle] | None:
    try:
        subtitles: list[Subtitle] = []
        reply = grpc_app.dm_view(aid, cid)
        if reply is None or reply.subtitle is None:
            return None
        for item in reply.subtitle.subtitles:
            subtitles.append(
                Subtitle(
                    lan=item.lan or "",
                    url=item.subtitle_url or "",
                    path=f"{aid}/{aid}.{cid}.{item.lan}.srt",
                )
            )
        if any(not item.url for item in subtitles):
            raise RuntimeError("Bad url")
        return subtitles
    except Exception:
        return None


def get_subtitles(
    aid: str, cid: str, ep_id: str, index: int, intl: bool
) -> list[Subtitle]:
    """按优先级尝试各字幕接口，返回可用的字幕列表。"""
    if intl:
        subtitles = _get_intl_subtitles_api1(aid, cid, ep_id, index)
        if subtitles is None:
            subtitles = _get_intl_subtitles_api2(aid, cid, ep_id, index)
    elif Config.COOKIE == "":
        # 未登录只有 APP 接口能拿到字幕
        subtitles = _get_subtitles_api3(aid, cid, ep_id, index)
    else:
        subtitles = (
            _get_subtitles_api2(aid, cid, ep_id, index)
            or _get_subtitles_api1(aid, cid, ep_id, index)
            or _get_subtitles_api3(aid, cid, ep_id, index)
        )

    if subtitles is None:
        return []

    for item in subtitles:
        if item.url.startswith("//"):
            item.url = "https:" + item.url
    return subtitles


# ---------------------------------------------------------------------------
# 保存
# ---------------------------------------------------------------------------


def save_subtitle(url: str, path: str) -> None:
    from pathlib import Path

    Path(path).parent.mkdir(parents=True, exist_ok=True)
    content = HTTPUtil.get_web_source(url)
    if path.endswith(".srt"):
        content = convert_sub_from_json(content)
    Path(path).write_text(content, encoding="utf-8")


def convert_sub_from_json(json_string: str) -> str:
    """B 站字幕 JSON -> SRT。"""
    payload = json.loads(json_string)
    lines: list[str] = []
    body = payload.get("body") or []
    for i, line in enumerate(body):
        lines.append(str(i + 1))
        start = _format_time(float(line.get("from", 0.0)))
        end = _format_time(float(line.get("to", 0.0)))
        lines.append(f"{start} --> {end}")
        if "content" in line:
            lines.append(str(line["content"]))
        lines.append("")
    return "\n".join(lines) + ("\n" if lines else "")


def _format_time(sec: float) -> str:
    """秒 -> ``hh:mm:ss,fff``。"""
    total_ms = int(round(sec * 1000))
    hours = total_ms // 3_600_000 % 24
    minutes = total_ms // 60_000 % 60
    seconds = total_ms // 1000 % 60
    millis = total_ms % 1000
    return f"{hours:02d}:{minutes:02d}:{seconds:02d},{millis:03d}"
